import { GameLayout, StickerPlacement } from '../../core/GameSession';
import { validateRenderableLayout } from '../../core/RenderableLayout';
const object = (v: unknown): v is Record<string, unknown> => !!v && typeof v === 'object' && !Array.isArray(v);
const same = (a: unknown, b: unknown): boolean => JSON.stringify(a) === JSON.stringify(b);
const order = (v: unknown): v is number => typeof v === 'number' && Number.isSafeInteger(v) && v > 0;
const field = (row: unknown, key: string): unknown => object(row) ? row[key] : undefined;
const key = (row: unknown): string => field(row, 'kind') === 'fixed' ? `fixed:${field(row, 'fixedId')}`
  : `part:${field(row, 'stickerId')}:${field(row, 'partId')}`;
const immutablePart = ['partId', 'partIndex', 'assetKey', 'file', 'sourceSize', 'offset', 'anchor', 'scale', 'rotation', 'requiresAssetIds', 'fullAssetKey', 'fullFile', 'assemblyOnly', 'sourcePartKind'];
const immutableFixed = ['fixedId', 'assetKey', 'file', 'sourceSize', 'position', 'anchor', 'scale', 'rotation', 'requiresAssetIds'];

/**
 * GameSession validates play state. This additionally guards renderer resources.
 * A draft may change logical parameters but cannot replace PNGs or drop a part.
 */
export function validateOnsenDraft(value: unknown, source: GameLayout): string[] {
  let errors: string[];
  try { errors = validateRenderableLayout(value, source); }
  catch { return ['malformed renderer metadata']; }
  if (errors.length || !object(value)) return errors;
  const draft = value as unknown as GameLayout;
  if (draft.sceneId !== source.sceneId) errors.push('sceneId differs from source');
  if (!object(draft.scene) || !object(source.scene)
    || ['width', 'height', 'baseAssetKey', 'referenceAssetKey'].some(k => field(draft.scene, k) !== field(source.scene, k))) errors.push('scene resources or dimensions changed');
  if (draft.stickers.length !== source.stickers.length) errors.push('logical sticker count changed');
  const sourceIds = new Set(source.stickers.map(s => s.stickerId));
  if (draft.stickers.some(s => !sourceIds.has(s.stickerId))) errors.push('unknown logical sticker ID');
  if (draft.geoBlocks.length !== source.geoBlocks.length || draft.geoBlocks.some(block =>
    !source.geoBlocks.some(original => original.blockId === block.blockId && original.blockOrder === block.blockOrder))) errors.push('geographic block identities/order changed');
  for (const original of source.stickers) {
    const row = draft.stickers.find(s => s.stickerId === original.stickerId);
    if (!row) { errors.push(`missing sticker ${original.stickerId}`); continue; }
    if (['file', 'assetKey', 'sourceSize', 'dependsOn'].some(k => !same(row[k], original[k]))) errors.push(`immutable sticker resource changed: ${row.stickerId}`);
    const parts = row.renderParts; const originalParts = original.renderParts ?? [];
    if (!Array.isArray(parts) || parts.length !== originalParts.length) { errors.push(`render parts missing: ${row.stickerId}`); continue; }
    if (parts.some(part => !object(part))) { errors.push(`malformed render part: ${row.stickerId}`); continue; }
    if (new Set(parts.map(p => p.partId)).size !== parts.length) errors.push(`duplicate part ID: ${row.stickerId}`);
    for (const sourcePart of originalParts) {
      const part = parts.find(p => p.partId === sourcePart.partId);
      if (!part || immutablePart.some(k => !same(part[k], sourcePart[k]))) errors.push(`immutable part resource changed: ${sourcePart.partId}`);
      else if (!order(part.placementOrder) || !Number.isSafeInteger(part.layerIndex)) errors.push(`invalid part painter order: ${sourcePart.partId}`);
    }
    if (parts.length && row.placementOrder !== Math.min(...parts.map(p => p.placementOrder))) errors.push(`logical order differs from first part: ${row.stickerId}`);
  }
  const fixed = draft.fixedLayers; const originalFixed = source.fixedLayers ?? [];
  if (!Array.isArray(fixed) || fixed.length !== originalFixed.length) errors.push('fixed foreground layers missing');
  else {
    if (fixed.some(row => !object(row))) { errors.push('malformed fixed foreground layer'); return errors; }
    if (new Set(fixed.map(f => f.fixedId)).size !== fixed.length) errors.push('duplicate fixed layer ID');
    for (const sourceFixed of originalFixed) {
      const row = fixed.find(f => f.fixedId === sourceFixed.fixedId);
      if (!row || immutableFixed.some(k => !same(row[k], sourceFixed[k]))) errors.push(`fixed resource changed: ${sourceFixed.fixedId}`);
    }
  }
  const render = draft.renderOrder; const sourceRender = source.renderOrder ?? [];
  if (!Array.isArray(render) || render.length !== sourceRender.length) errors.push('global render queue missing');
  else {
    if (render.some(row => !object(row))) { errors.push('malformed global render queue entry'); return errors; }
    const expected = new Set(sourceRender.map(key)); const actual = render.map(key);
    if (new Set(actual).size !== expected.size || actual.some(k => !expected.has(k))) errors.push('global render queue does not cover source entries exactly once');
    if (render.some(r => !order(r.placementOrder) || !Number.isSafeInteger(r.layerIndex))
      || new Set(render.map(r => r.placementOrder)).size !== render.length) errors.push('global painter orders must be unique positive integers');
    for (const row of render) {
      const owner: StickerPlacement | undefined = draft.stickers.find(s => s.stickerId === row.stickerId);
      const layer = row.kind === 'fixed' ? fixed?.find(f => f.fixedId === row.fixedId)
        : owner?.renderParts?.find(p => p.partId === row.partId);
      if (!layer || row.placementOrder !== layer.placementOrder || row.layerIndex !== layer.layerIndex) errors.push(`global queue differs from renderer layer: ${key(row)}`);
    }
  }
  return errors;
}

import { validateLayout } from './GameSession';

/** Gameplay validation alone is insufficient for externally imported artwork layouts. */
export function validateRenderableLayout(value: any, source?: any): string[] {
  const errors = validateLayout(value);
  if (!value || typeof value !== 'object') return errors;
  if (errors.length) return errors;
  const validNumber = (n: any) => typeof n === 'number' && Number.isFinite(n);
  const size = (s: any) => s && validNumber(s.width) && validNumber(s.height) && s.width > 0 && s.height > 0;
  const point = (p: any) => p && validNumber(p.x) && validNumber(p.y);
  const polygonPoint = (p: any) => Array.isArray(p) ? p.length === 2 && p.every(validNumber) : point(p);
  const rect = (r: any) => point(r) && size(r);
  const dependencies = (ids: any) => Array.isArray(ids) && ids.every(id => typeof id === 'string' && value.stickers.some((s: any) => s?.stickerId === id));
  const asset = (key: any) => typeof key === 'string' && key.startsWith('resources/') && !key.split('/').includes('..') && !key.includes(':') && !key.includes('\\');
  if (!size(value.scene) || !asset(value.scene?.baseAssetKey) || !asset(value.scene?.referenceAssetKey)) errors.push('scene dimensions and artwork keys are required');
  if (value.scene?.basePatches !== undefined && !Array.isArray(value.scene.basePatches)) errors.push('basePatches must be an array');
  else for (const p of value.scene?.basePatches || []) if (!p || !asset(p.assetKey) || !point(p.position) || !size(p.sourceSize) || !size(p.size)) errors.push('invalid background repair tile');
  if (!Number.isSafeInteger(value.layoutRevision) || value.layoutRevision < 1) errors.push('renderable layoutRevision must be a positive integer');
  if (!Array.isArray(value.fixedLayers) || !Array.isArray(value.renderOrder) || !Array.isArray(value.stickers)) return [...errors, 'fixedLayers, renderOrder and stickers are required'];
  if (!value.stickers.length) errors.push('a renderable scene must contain stickers');
  for (const b of value.geoBlocks || []) {
    if (!b || !rect(b.bounds) || !rect(b.cameraBounds) || !Array.isArray(b.polygon) || b.polygon.length < 3 || !b.polygon.every(polygonPoint)) errors.push('geometric blocks require valid bounds, camera bounds and polygons');
  }
  const parts = new Map<string, any>();
  const logical = new Map<string, any>();
  const fixed = new Map<string, any>();
  for (const s of value.stickers) {
    if (!s || !asset(s.assetKey) || !size(s.sourceSize)) { errors.push('invalid sticker artwork'); continue; }
    logical.set(s.stickerId, s);
    if (!Array.isArray(s.renderParts) || !s.renderParts.length) { errors.push(`${s.stickerId} requires complete renderParts`); continue; }
    for (const p of s.renderParts) {
      if (!p || typeof p.partId !== 'string' || parts.has(p.partId) || !asset(p.assetKey) || !size(p.sourceSize) || !point(p.offset) || !Number.isSafeInteger(p.layerIndex) || !dependencies(p.requiresAssetIds)) errors.push(`${s.stickerId} invalid render part`);
