      if (p?.fullAssetKey !== undefined && !asset(p.fullAssetKey)) errors.push(`${s.stickerId} invalid complete artwork key`);
      if (p?.fullFile !== undefined && !asset(p.fullFile)) errors.push(`${s.stickerId} invalid complete artwork file`);
      if (p?.assemblyOnly !== undefined && typeof p.assemblyOnly !== 'boolean') errors.push(`${s.stickerId} invalid assembly overlay flag`);
      if (p?.sourcePartKind !== undefined && typeof p.sourcePartKind !== 'string') errors.push(`${s.stickerId} invalid source part kind`);
    }
  }
  for (const f of value.fixedLayers) {
    if (!f || typeof f.fixedId !== 'string' || fixed.has(f.fixedId) || !asset(f.assetKey) || !size(f.sourceSize) || !point(f.position) || !point(f.anchor) || !validNumber(f.scale) || f.scale <= 0 || !validNumber(f.rotation) || !Number.isSafeInteger(f.layerIndex) || !dependencies(f.requiresAssetIds)) errors.push('invalid fixed layer');
