    orders.add(e.placementOrder);
    const key = e.kind === 'fixed' ? `fixed:${e.fixedId}` : `part:${e.partId}`;
    const target = e.kind === 'fixed' ? fixed.get(e.fixedId) : parts.get(e.partId);
    if (!target || keys.has(key) || target.placementOrder !== e.placementOrder || target.layerIndex !== e.layerIndex) errors.push(`invalid paint entry ${key}`);
    if (e.kind === 'stickerPart' && !logical.get(e.stickerId)?.renderParts?.some((p: any) => p.partId === e.partId)) errors.push('paint owner mismatch');
    keys.add(key);
  }
